import { Suspense } from 'react'
import { getProjectDetails, getProjectTitle } from '@/lib/data'

export default async function ProjectPage({
  params,
}: PageProps<'/projects/[slug]'>) {
  const { slug } = await params

  // The title is cacheable, so it is prerendered into the static shell and
  // prefetched together with the dashboard link. It appears instantly on
  // navigation without waiting for the rest of the page.
  const title = await getProjectTitle(slug)

  return (
    <main>
      <h1>{title}</h1>
      {/* The details are dynamic and stream in on navigation, so they are not
          prefetched while the user is on the dashboard. */}
      <Suspense fallback={<p>Loading details...</p>}>
        <Details slug={slug} />
      </Suspense>
    </main>
  )
}

async function Details({ slug }: { slug: string }) {
  const details = await getProjectDetails(slug)

  return (
    <>
      <p>{details.description}</p>
      <h2>Recent activity</h2>
      <ul>
        {details.activity.map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>
    </>
  )
}

