import { getProjectDetails, getProjectSlugs, getProjectTitle } from '@/lib/data'

// Prerender each known project so its `params` (slug) are known at build time.
// That lets the cacheable title be prerendered into the static shell below.
export function generateStaticParams() {
  return getProjectSlugs().map((slug) => ({ slug }))
}

export default async function ProjectPage({
  params,
}: PageProps<'/projects/[slug]'>) {
  const { slug } = await params

  // The title is cacheable and the slug is known at build time, so it is
  // prerendered into the static shell and prefetched with the dashboard link.
  // It appears instantly on navigation.
  const title = await getProjectTitle(slug)

  return (
    <main>
      <h1>{title}</h1>
      {/*
        The details are dynamic, so this Suspense boundary is deferred: only
        its fallback is prerendered, and the real content streams in on
        navigation. It is not prefetched while the user is on the dashboard.
      */}
      <Suspense fallback={<p>Loading details...</p>}>
        <Details slug={slug} />
      </Suspense>
    </main>
  )
}

async function Details({ slug }: { slug: string }) {
  const details = await getProjectDetails(slug)

  return (
    <>
      <p>{details.description}</p>
      <h2>Recent activity</h2>
      <ul>
        {details.activity.map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>
    </>
  )
}

